'use strict';

/**
 * Generated by `aid infra gen`. Do not edit: the next run refuses to overwrite a
 * hand-edited file, and the construct carries no project fact to preserve.
 *
 * The AWS CDK spelling of `infra/generated/modules/edge`: one published Lambda@Edge
 * function and one CloudFront distribution whose default behaviour answers every request
 * from it.
 *
 * Lambda@Edge is not a smaller Lambda: it takes no environment, no VPC, no layers and no
 * container image, caps a request at 30 seconds, and must be published as a numbered
 * version in us-east-1. Configuration therefore travels in Secrets Manager, and the
 * construct refuses a stack outside us-east-1 rather than synthesising a template AWS
 * would reject at deploy time.
 *
 * Business inputs stay inputs: the zip to deploy, the domains and certificate, the price
 * class and the sizing arrive in `inputs`, never in this file.
 */

const cdk = require('aws-cdk-lib');
const cloudfront = require('aws-cdk-lib/aws-cloudfront');
const origins = require('aws-cdk-lib/aws-cloudfront-origins');
const fs = require('node:fs');
const iam = require('aws-cdk-lib/aws-iam');
const lambda = require('aws-cdk-lib/aws-lambda');
const path = require('node:path');
const secretsmanager = require('aws-cdk-lib/aws-secretsmanager');

/** Names in IAM and Lambda allow letters, digits, hyphens and underscores only. */
function sanitize(value) {
  return value.replace(/[^A-Za-z0-9-_]/g, '-');
}

function limited(value, length) {
  return value.slice(0, length);
}

function nameOf(project, id) {
  return limited(sanitize(project.namespace + '-' + project.name + '-' + id), 64);
}

function priceClassOf(value) {
  if (value === 'PriceClass_All') return cloudfront.PriceClass.PRICE_CLASS_ALL;
  if (value === 'PriceClass_200') return cloudfront.PriceClass.PRICE_CLASS_200;
  return cloudfront.PriceClass.PRICE_CLASS_100;
}

function addEdge(scope, context, inputs) {
  const deployments = Object.keys(context.services).filter(
    (id) => context.services[id].target === 'edge',
  );

  const result = { distribution: undefined, functions: {}, secrets: {} };
  if (deployments.length === 0) return result;

  // One distribution serves the project, so a second edge deployment would have nowhere
  // to attach. The HCL module refuses the same shape.
  if (deployments.length > 1) {
    throw new Error(
      'The plan declares ' + deployments.length + ' edge deployments; one CloudFront ' +
        'distribution serves the app, so keep one edge deployment and let it own every ' +
        'HTTP route.',
    );
  }

  // CloudFront associates a version that exists in us-east-1. Synthesising a template for
  // another region produces a stack AWS rejects only at deploy time, so refuse here.
  const region = cdk.Stack.of(scope).region;
  if (region !== 'us-east-1') {
    throw new Error(
      'Lambda@Edge must be created in us-east-1, but this stack targets "' + region + '". ' +
        'Create the edge stack with env.region "us-east-1" and call addEdge from it.',
    );
  }

  const id = deployments[0];
  const service = context.services[id];

  if (service.streaming) {
    throw new Error(
      'Deployment "' + id + '" declares streaming, which a CloudFront response cannot ' +
        'deliver. Serve it from a container target.',
    );
  }

  const size = (inputs.edgeSizing || {})[id] || {};
  const timeout = size.timeoutSeconds === undefined ? 30 : size.timeoutSeconds;
  if (timeout > 30) {
    throw new Error(
      'Lambda@Edge allows at most 30 seconds for a request; deployment "' + id +
        '" asks for more.',
    );
  }

  const memory = size.memoryMb === undefined ? 512 : size.memoryMb;
  if (memory < 128 || memory > 3008) {
    throw new Error(
      'Lambda@Edge accepts 128 to 3008 MB; deployment "' + id + '" is outside that range.',
    );
  }

  const zipPath = inputs.edgeZipPath || 'edge.zip';
  if (!fs.existsSync(zipPath)) {
    throw new Error(
      'No Lambda zip at "' + path.resolve(zipPath) + '". Build the app into that file ' +
        'before planning; the function deploys that archive.',
    );
  }

  const aliases = inputs.edgeAliases || [];
  const certificateArn = inputs.edgeCertificateArn || '';
  if (aliases.length > 0 && !certificateArn) {
    throw new Error(
      'edgeAliases names ' + aliases.length + ' domain(s), but no edgeCertificateArn ' +
        'was supplied. A custom domain needs an ACM certificate in us-east-1.',
    );
  }

  const functionName = nameOf(context.project, id);

  // Lambda@Edge is assumed by CloudFront as well as Lambda, and a basic execution role
  // covers only the log group the function writes.
  const role = new iam.Role(scope, id + 'EdgeRole', {
    roleName: limited(functionName, 59) + '-edge',
    assumedBy: new iam.CompositePrincipal(
      new iam.ServicePrincipal('lambda.amazonaws.com'),
      new iam.ServicePrincipal('edgelambda.amazonaws.com'),
    ),
    managedPolicies: [
      iam.ManagedPolicy.fromAwsManagedPolicyName('service-role/AWSLambdaBasicExecutionRole'),
    ],
  });

  // Lambda@Edge takes no environment variables, so the app reads its configuration from
  // this secret. An empty secret is the placeholder the deploy step fills, and a zero
  // recovery window lets a replaced one disappear immediately.
  const secret = new secretsmanager.CfnSecret(scope, id + 'EdgeSecret', {
    name: functionName,
    description: 'Environment values for the AID edge handler.',
    recoveryWindowInDays: 0,
  });
  role.addToPolicy(
    new iam.PolicyStatement({
      actions: ['secretsmanager:GetSecretValue'],
      resources: [secret.ref],
    }),
  );

  if ((service.providers || []).includes('bedrock')) {
    role.addToPolicy(
      new iam.PolicyStatement({
        actions: ['bedrock:InvokeModel'],
        resources: [
          'arn:' + cdk.Aws.PARTITION + ':bedrock:*::foundation-model/*',
          'arn:' + cdk.Aws.PARTITION + ':bedrock:*:' + cdk.Aws.ACCOUNT_ID + ':inference-profile/*',
        ],
      }),
    );
  }

  const fn = new lambda.Function(scope, id + 'EdgeFunction', {
    functionName: functionName,
    role: role,
    runtime: lambda.Runtime.PYTHON_3_12,
    handler: 'app.generated.edge.handler',
    code: lambda.Code.fromAsset(zipPath),
    memorySize: memory,
    timeout: cdk.Duration.seconds(timeout),
  });

  // CloudFront associates a numbered version, never $LATEST and never an alias.
  const version = fn.currentVersion;
  version.addPermission('cloudfront', {
    principal: new iam.ServicePrincipal('edgelambda.amazonaws.com'),
    sourceArn:
      'arn:' + cdk.Aws.PARTITION + ':cloudfront::' + cdk.Aws.ACCOUNT_ID + ':distribution/*',
  });

  const distribution = new cloudfront.Distribution(scope, id + 'EdgeDistribution', {
    comment: context.project.namespace + '-' + context.project.name + ' edge app',
    priceClass: priceClassOf(inputs.edgePriceClass),
    enableIpv6: true,
    domainNames: aliases,
    certificate:
      certificateArn === ''
        ? undefined
        : cloudfront.Certificate.fromCertificateArn(scope, 'EdgeCertificate', certificateArn),
    minimumProtocolVersion:
      certificateArn === '' ? undefined : cloudfront.SecurityPolicyProtocol.TLS_V1_2_2021,
    defaultBehavior: {
      // The function answers every request, so this origin exists only because a
      // distribution requires one; it is never reached.
      origin: new origins.HttpOrigin('example.com', {
        protocolPolicy: cloudfront.OriginProtocolPolicy.HTTPS_ONLY,
      }),
      viewerProtocolPolicy: cloudfront.ViewerProtocolPolicy.REDIRECT_TO_HTTPS,
      allowedMethods: cloudfront.AllowedMethods.ALLOW_ALL,
      cachedMethods: cloudfront.CachedMethods.CACHE_GET_HEAD,
      cachePolicy: cloudfront.CachePolicy.CACHING_DISABLED,
      originRequestPolicy: cloudfront.OriginRequestPolicy.ALL_VIEWER,
      edgeLambdas: [
        {
          functionVersion: version,
          eventType: cloudfront.LambdaEdgeEventType.ORIGIN_REQUEST,
          includeBody: true,
        },
      ],
    },
  });

  result.distribution = distribution;
  result.functions[id] = version.functionArn;
  result.secrets[id] = secret.ref;
  return result;
}

module.exports = { addEdge: addEdge };
